$ErrorActionPreference = "Stop"

if (!(Test-Path ".\game")) {
    Write-Host "ERROR: Ejecuta este parche desde la carpeta raiz del proyecto, donde existe game\" -ForegroundColor Red
    exit 1
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = ".\_v06_backup_$stamp"
New-Item -ItemType Directory -Path $backup -Force | Out-Null

# Necesitamos primero la base visual v0.5.
$required = @(
    ".\game\images\ui\village_night_bg.png",
    ".\game\images\ui\nightfall_logo.png",
    ".\game\images\ui\icons\icon_map.png"
)

foreach ($f in $required) {
    if (!(Test-Path $f)) {
        Write-Host "FALTA: $f" -ForegroundColor Yellow
        Write-Host "La v0.6 necesita que el parche visual v0.5 se haya instalado correctamente." -ForegroundColor Yellow
        exit 1
    }
}

# Desactivar overrides anteriores de esta misma capa visual.
foreach ($candidate in @(
    ".\game\zzzzz_hos_showcase_ui.rpy",
    ".\game\zzzzzz_visual_polish_v06.rpy",
    ".\game\v06_aya_demo.rpy"
)) {
    if (Test-Path $candidate) {
        Copy-Item -LiteralPath $candidate -Destination $backup -Force
        Move-Item -LiteralPath $candidate -Destination ($candidate + ".disabled.$stamp") -Force
    }
}

New-Item -ItemType Directory -Path ".\game\images\characters\aya" -Force | Out-Null
New-Item -ItemType Directory -Path ".\game\images\ui\polish" -Force | Out-Null


@'

